<script setup lang="ts">
import { computed, ref } from 'vue'
import type { ApiClient } from '../../api'
import { duration } from '../../duration'
import { dateTime } from '../../types'
import { useResource } from '../../composables/useResource'
import { invitationSettingsSchema, invitationRecordsSchema, type InvitationSettings, type Invitation } from '../../components/business-rewick/invitations'
import PageHeader from '../../components/ui/PageHeader.vue'
import Button from '../../components/ui/Button.vue'
import Panel from '../../components/ui/Panel.vue'
import Field from '../../components/ui/Field.vue'
import TextInput from '../../components/ui/TextInput.vue'
import DataTable from '../../components/ui/DataTable.vue'
import Pagination from '../../components/ui/Pagination.vue'
import Tag from '../../components/ui/Tag.vue'
import Modal from '../../components/ui/Modal.vue'
import Avatar from '../../components/ui/Avatar.vue'
import InvitationSettingsEditor from '../../components/business-rewick/InvitationSettingsEditor.vue'
const props = defineProps<{ api: ApiClient; active?: boolean }>()
const settings = useResource(props.api, '/admin/invitation-settings', invitationSettingsSchema)
const editing = ref(false), savedSettings = ref<InvitationSettings | null>(null), notice = ref(''), selected = ref<Invitation | null>(null), query = ref(''), search = ref(''), page = ref(1)
const { state, reload } = useResource(props.api, () => `/admin/invitations?${new URLSearchParams({ search: search.value, page: String(page.value), size: '20' })}`, invitationRecordsSchema)
const current = computed(() => savedSettings.value ?? (settings.state.value.kind === 'ready' ? settings.state.value.data : null))
const columns = [{ key: 'inviter', title: '邀请人' }, { key: 'invitee', title: '新用户' }, { key: 'code', title: '邀请码' }, { key: 'reward', title: '奖励时长' }, { key: 'createdAt', title: '注册时间' }, { key: 'status', title: '发放状态' }, { key: 'actions', title: '操作', className: 'col-actions' }]
function applySearch() { const next = query.value.trim(); if (search.value === next && page.value === 1) reload(); search.value = next; page.value = 1 }
function reloadSettings() { editing.value = false; savedSettings.value = null; settings.reload() }
function saved(value: InvitationSettings) { savedSettings.value = value; editing.value = false; notice.value = '邀请奖励配置已保存。' }
</script>
<template><div class="page"><PageHeader title="邀请奖励" desc="管理邀请规则与奖励发放" /><div class="stack"><p v-if="notice" role="status" class="business-notice business-feedback">{{ notice }}</p><Panel v-if="current" class="reveal" title="当前奖励规则"><template #tools><Button icon="edit" @click="editing = true">修改规则</Button></template><div class="reward-summary"><div><h3>邀请奖励{{ current.enabled ? '已开启' : '已关闭' }}</h3><p class="muted">通过邀请码邀请新用户注册，获得面试时长奖励。</p></div><div><span class="muted">每成功邀请一人，奖励邀请人</span><strong class="reward-value tnum">{{ current.rewardSeconds % 60 === 0 ? `${current.rewardSeconds / 60} 分钟` : duration(current.rewardSeconds) }}</strong></div><div><span class="muted">奖励触发条件</span><h3>邮箱验证并注册成功</h3><p class="muted">修改规则不影响已获得的时长。</p></div></div></Panel><p v-else-if="settings.state.value.kind === 'error'" class="field-error" role="alert">{{ settings.state.value.error }}<Button @click="settings.reload">重试</Button></p><form class="search-form m-surface reveal" @submit.prevent="applySearch"><Field label="邮箱、显示名称或邀请码"><TextInput v-model="query" placeholder="搜索邮箱、名称或邀请码" icon="search" :maxlength="254" /></Field><div class="search-actions"><Button variant="primary" type="submit">搜索</Button></div></form><Panel class="reveal" title="邀请记录"><template #tools><Button icon="refresh" @click="reload">刷新记录</Button></template><p v-if="state.kind === 'error'" class="field-error" role="alert">{{ state.error }}<Button @click="reload">重试</Button></p><DataTable v-if="state.kind !== 'error'" :columns="columns" :data="state.kind === 'ready' ? state.data.items : []" :loading="state.kind === 'loading'" :min-width="1000" empty-text="暂无匹配的邀请记录。"><template #cell-inviter="{ row }"><div class="cell-main"><Avatar :name="row.inviterName" /><span>{{ row.inviterName }}<small class="muted cell-sub">{{ row.inviterEmail }}</small></span></div></template><template #cell-invitee="{ row }"><div class="cell-main"><Avatar :name="row.inviteeName" /><span>{{ row.inviteeName }}<small class="muted cell-sub">{{ row.inviteeEmail }}</small></span></div></template><template #cell-reward="{ row }"><span class="tnum">{{ duration(row.rewardSeconds) }}</span></template><template #cell-createdAt="{ row }">{{ dateTime(row.createdAt) }}</template><template #cell-status><Tag tone="ok" dot>已发放</Tag></template><template #cell-actions="{ row }"><Button variant="text" size="sm" @click="selected = row">查看详情</Button></template></DataTable><Pagination v-if="state.kind === 'ready'" :page="state.data.page" :page-size="state.data.size" :sizes="[20]" :total="state.data.total" @update:page="page = $event" /></Panel><InvitationSettingsEditor v-if="editing && current" :api="api" :initial="current" @close="editing = false" @reload="reloadSettings" @saved="saved" /><Modal :open="Boolean(selected)" title="邀请奖励详情" @close="selected = null"><dl v-if="selected" class="kv-grid"><div class="kv"><dt class="kv-label">邀请人</dt><dd class="kv-value">{{ selected.inviterName }}<small class="muted cell-sub">{{ selected.inviterEmail }}</small></dd></div><div class="kv"><dt class="kv-label">新用户</dt><dd class="kv-value">{{ selected.inviteeName }}<small class="muted cell-sub">{{ selected.inviteeEmail }}</small></dd></div><div class="kv"><dt class="kv-label">邀请码</dt><dd class="kv-value">{{ selected.code }}</dd></div><div class="kv"><dt class="kv-label">奖励时长</dt><dd class="kv-value">{{ duration(selected.rewardSeconds) }}</dd></div><div class="kv"><dt class="kv-label">注册时间</dt><dd class="kv-value">{{ dateTime(selected.createdAt) }}</dd></div><div class="kv"><dt class="kv-label">发放状态</dt><dd class="kv-value">已发放</dd></div></dl></Modal></div></div></template>
<style scoped>.cell-sub{display:block;}.reward-summary { display:grid;grid-template-columns:1.2fr 1fr 1.2fr;gap:24px;padding:20px;align-items:center;}.reward-value{display:block;font-size:32px;line-height:1.4;color:var(--blue);margin-top:8px;}.page>.panel{margin-bottom:20px;}@media(max-width:900px){.reward-summary{grid-template-columns:minmax(0,1fr);}}</style>
